import React,{useState} from 'react';
type Proposal={title:string;fileId:string};
export function PlanningScreen({storeId,proposal,onSubmit}:{storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void}){return <ProposalForm key={storeId} storeId={storeId} proposal={proposal} onSubmit={onSubmit}/>;}
function ProposalForm({storeId,proposal,onSubmit}:{storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void}){const [form,setForm]=useState<Proposal>({title:'',fileId:''});const [reason,setReason]=useState('');const [startedUnfinished,setStartedUnfinished]=useState(false);const [scheduledAt,setScheduledAt]=useState('');const [window,setWindow]=useState<{from:number;to:number}>();
  const requiresReason=startedUnfinished;
  const validSchedule=()=>{if(!window)return true;const at=Date.parse(scheduledAt);return Number.isFinite(at)&&at>=window.from&&at<window.to;};
  return <form onSubmit={e=>{e.preventDefault();if((requiresReason&&!reason.trim())||!validSchedule())return;onSubmit({storeId,...form,...(scheduledAt?{scheduledAt:Date.parse(scheduledAt)}:{}),...(requiresReason?{reason:reason.trim()}:{} )});}}>
    <input aria-label="Title" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/>
    <input aria-label="File" value={form.fileId} onChange={e=>setForm({...form,fileId:e.target.value})}/>
    <button type="button" onClick={()=>proposal&&setForm({...proposal})}>Use upload</button>
    <label><input type="checkbox" aria-label="Started unfinished" checked={startedUnfinished} onChange={e=>setStartedUnfinished(e.target.checked)}/>Started and unfinished</label>
    {requiresReason&&<label>Reason<input aria-label="Reason" value={reason} onChange={e=>setReason(e.target.value)} required/></label>}
    <label>Schedule<input aria-label="Schedule" type="datetime-local" value={scheduledAt} onChange={e=>setScheduledAt(e.target.value)}/></label>
    <label>Window start<input aria-label="Window start" type="datetime-local" value={window?new Date(window.from).toISOString().slice(0,16):''} onChange={e=>setWindow({...window,from:Date.parse(e.target.value)})}/></label>
    <label>Window end<input aria-label="Window end" type="datetime-local" value={window?new Date(window.to).toISOString().slice(0,16):''} onChange={e=>setWindow({...window,to:Date.parse(e.target.value)})}/></label>
    <button type="submit" disabled={(requiresReason&&!reason.trim())||!validSchedule()}>Save</button>
  </form>;}

