import {deliveryWindow,requiresReason,type Stop} from './domain';

// The API expects the item's 1-based rank in the active list. Stored positions
// can have gaps after removals, so they are not valid destination ranks.
export function moveUp(stops:Stop[],activeIndex:number){
  const active=stops.filter(stop=>!stop.removed);
  if(activeIndex<=0||activeIndex>=active.length) throw new RangeError('activeIndex must identify a movable active stop');
  return {id:active[activeIndex].id,position:activeIndex};
}

export const screenRequiresReason=requiresReason;

export function fitsWindow(at:number,notice:{sentAt:number},appointments:{at:number;status:string}[],now:number){
  const window=deliveryWindow(notice,appointments,now);
  return Boolean(window&&at>=window.from&&at<window.to);
}

