import {test,expect} from 'bun:test';
import {fitsWindow,moveUp,screenRequiresReason} from './logic';
import {deliveryWindow,requiresReason,type Stop} from './domain';

test('schedule window includes notification and excludes next appointment',()=>{
  const appointments=[{at:40,status:'CANCELLED'},{at:20,status:'HELD'},{at:30,status:'PLANNED'},{at:50,status:'PLANNED'}];
  expect(deliveryWindow({sentAt:10},appointments,10)).toEqual({from:10,to:30});
  expect(fitsWindow(10,{sentAt:10},appointments,10)).toBe(true);
  expect(fitsWindow(9,{sentAt:10},appointments,10)).toBe(false);
  expect(fitsWindow(30,{sentAt:10},appointments,10)).toBe(false);
  expect(fitsWindow(31,{sentAt:10},appointments,10)).toBe(false);
  expect(fitsWindow(29,{sentAt:10},appointments,10)).toBe(true);
});

test('move destination is active rank after removed stop leaves position gap',()=>{
  const stops:Stop[]=[{id:'a',position:1,status:'NEW'},{id:'b',position:2,status:'NEW',removed:true},{id:'c',position:3,status:'NEW'},{id:'d',position:4,status:'NEW'}];
  expect(moveUp(stops,2)).toEqual({id:'d',position:2});
});

test('reason state is shared for started unfinished paths and their complement',()=>{
  const started:Stop={id:'a',position:1,status:'IN_PROGRESS',startedOn:'2026-01-01'};
  const postponed:Stop={...started,status:'POSTPONED'};
  const done:Stop={...started,status:'DONE'};
  const neverStarted:Stop={...started,status:'POSTPONED',startedOn:undefined};
  for(const stop of [started,postponed]) expect(screenRequiresReason(stop)).toBe(requiresReason(stop));
  expect(requiresReason(postponed)).toBe(true);
  expect(requiresReason(done)).toBe(false);
  expect(requiresReason(neverStarted)).toBe(false);
});
